# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
from author_batch200_root_lev_a import L,A
EL=L+[['拉丁 ex- + levare → elevare，分词 elevatus','向外、向上抬起'],['英语 elevate','抬高；提升地位或程度']]
LE=L+[['拉丁 levator → 古法语 leveor／leveur','抬举者、用来抬的东西'],['英语 lever','杠杆；撬动']]
LY=L+[['古法语 lever → levée','抬起、筹集 → 征集、征收'],['盎格鲁法语 leve → 英语 levy','征收款项、征集人员；征收额']]
WB=[
E('elevate','/ˈeləveɪt/','抬高；提升；使升高','把东西从原来的位置往上托，也可以把地位或水平往上提。','拉丁 e- 是 ex- 的形式，加 levare“抬起”；英语借用 elevatus 的词干。',EL,'elevate a platform 是把平台升高；elevate someone to a position 是把某人提升到某个职位；elevate a discussion 是让讨论有更高的质量。具体或抽象的“向上”都能成立。','elevate to；elevate above；elevate standards。','raise 更日常；elevate 较正式，常让人想到位置、地位、水平的提升，不等于所有语境都能互换。',('The mechanism elevates the platform slowly.','这个装置把平台缓缓升高。'),('Her careful questions elevated the quality of the discussion.','她细致的问题提升了讨论的质量。'),sources=['https://www.etymonline.com/word/elevate']),
E('elevated','/ˈeləveɪtɪd/','升高的；高架的；高于通常水平的','一个东西被抬到上面，或某个数值已经高过平常。','elevate + -d；词尾 /t/ 后的 -ed 读 /ɪd/。',A(EL,'英语 elevated','被抬高的 → 高架的、高于常态的'),'an elevated railway 是建在高架结构上的铁路；elevated costs 是上升的成本。elevated language 可以说庄重、高雅的语言，但高雅并不自动意味着更清楚。','an elevated walkway；elevated levels；an elevated position。','high 只说高；elevated 往往带着“高于地面、基准或通常状态”的比较背景。',('An elevated walkway connects the two buildings.','一条高架步道连接着两座楼。'),('The report noted elevated noise levels near the construction site.','报告指出工地附近的噪声水平偏高。')),
E('elevator','美 /ˈeləveɪtər/；英 /ˈelɪveɪtə/','电梯；升降装置；飞机升降舵','最初的画面是把东西提起来的东西，后来落到不同领域的具体装置上。','接拉丁 elevator“抬举者”与 elevare；现代可联系 elevate + -or，但英语早期还用于抬举肌肉，不能只从楼内电梯倒推历史。',L+[['拉丁 elevare → elevator','抬起 → 抬举者'],['英语 elevator 的早期解剖用法及机械用法','抬举肌肉；把物体升高的装置'],['现代常见 elevator','楼内升降机；另用于飞机俯仰操纵面等']],'美国英语里楼内的电梯叫 elevator，英国英语通常说 lift。飞机 elevator 调节机头上仰、下俯，名称保留“升降”的画面，但它不是舱内运人的小房间。grain elevator 又可指谷物提升装置及相关储运设施。','take the elevator；a freight elevator；the aircraft elevator。','escalator 是自动扶梯；elevator 常是沿井道升降的轿厢。飞机升降舵控制俯仰，不是只允许飞机向上。',('We took the elevator to the eighth floor.','我们乘电梯上了八楼。'),('The pilot checked the elevator before the training flight.','飞行员在训练飞行前检查了升降舵。'),sources=['https://www.etymonline.com/word/elevator','https://www.grc.nasa.gov/WWW/k-12/VirtualAero/BottleRocket/airplane/pitch.html']),
E('elevation','/ˌeləˈveɪʃən/','高度；抬高、提升；立面图','既可以说“往上抬”这件事，也可以说“抬到哪里、从正面看是什么样”。','经法语 elevation 接拉丁 elevatio，来自 elevare；与 elevate 同源，英语名词有自己的借入路线。',L+[['拉丁 elevare → elevatio','抬起 → 抬高这一动作'],['法语 elevation → 英语 elevation','升高、提升；高度；建筑立面']],'the elevation of a village 通常说村庄相对海平面等基准的高度。an elevation of a building 在建筑图纸里是从某一面正看过去的投影，不是俯视的平面图。elevation to office 则是职位晋升。','at an elevation of；above sea level；the front elevation。','elevation 是相对指定基准的高度；建筑的 front elevation 是正立面图，floor plan 是平面图。',('The village stands at an elevation of about one thousand metres.','这个村庄大约位于海拔一千米处。'),('The drawing shows the front elevation of the library.','这张图展示了图书馆的正立面。'),sources=['https://www.etymonline.com/word/elevation']),
E('lever','英 /ˈliːvə/；美 /ˈlevər/','杠杆；操纵杆；撬动；促成变化的手段','一根杆子绕支点转，把你的力传到另一端，撬动原本难动的东西。','古法语 leveor／leveur 接拉丁 levator“抬举者”，最终来自 levare。',LE,'push a lever 是推动操纵杆；lever a lid open 是用杠杆作用把盖子撬开。a policy lever 则把政策看作能带动结果变化的操作杆。这种比喻说的是作用点，不是保证一推就成功。','pull a lever；lever something open；a lever for change。','handle 是握住的把手；lever 强调杠杆或操纵作用。杠杆可以省力，但通常要用更大的移动距离交换，不会凭空增加能量。',('Pull the lever to release the seat.','拉动操纵杆，让座椅解锁。'),('They used a metal bar to lever the heavy lid open.','他们用一根金属杆把沉重的盖子撬开。'),sources=['https://www.etymonline.com/word/lever']),
E('leverage','英 /ˈliːvərɪdʒ/；美 /ˈlevərɪdʒ/','杠杆作用；影响力；借款形成的财务杠杆；利用','抓住一个有效支点，让手里有限的力量产生更大的作用。','lever + -age，先说杠杆作用，再引申到谈判影响力、资源利用和财务借力。',A(LE,'英语 leverage','杠杆作用 → 可用来影响局势的力量；财务杠杆'),'negotiating leverage 是你能影响谈判的筹码；leverage experience 是把已有经验用起来。金融里 leverage 涉及用借来的资金或其他方式放大敞口，收益和损失都可能放大。它不是“借钱就更赚钱”的结论。','have leverage；leverage over；financial leverage；leverage existing skills。','advantage 是优势；leverage 强调这种优势可以怎样撬动局面。日常写作里 leverage 作动词常可直接换成 use。',('The deadline gave the buyer more leverage in the negotiations.','这个截止期限让买方在谈判中多了一些筹码。'),('The team leveraged its previous experience to solve the problem.','团队利用以往经验解决了这个问题。'),sources=['https://www.etymonline.com/word/leverage','https://www.imf.org/external/pubs/ft/fandd/2012/06/claessens.htm']),
E('leveraged','英 /ˈliːvərɪdʒd/；美 /ˈlevərɪdʒd/','使用了杠杆的；大量依靠借款的；已被利用的','自有的力量之外又借了一股力，或已经把现有资源用上。','leverage + -d。',LE+[['英语 leverage → leveraged','利用杠杆或资源 → 已使用杠杆的、被利用的']],'a leveraged buyout 是借助大量债务融资进行的收购；a highly leveraged company 是债务相对相关资本或资产较高的公司，具体口径要看上下文。普通动词用法也可以说经验、关系已经被用来办事。','a leveraged buyout；highly leveraged；leveraged resources。','leveraged 不等于 profitable“盈利的”；它描述借力或融资方式，不能直接推出最终成败。',('The report compared leveraged and unleveraged investments.','报告比较了使用杠杆和未使用杠杆的投资。'),('She leveraged her language skills to help the international team.','她发挥自己的语言能力，帮助了国际团队。')),
E('deleverage','英 /diːˈliːvərɪdʒ/；美 /diːˈlevərɪdʒ/','去杠杆；降低债务杠杆','原来靠借来的钱撑得很大，现在把债务的相对分量降下来。','de- 表示减少、去除 + leverage。',LE+[['英语 leverage','利用借款等形成的财务杠杆'],['英语 de- + leverage → deleverage','降低债务杠杆']],'a company deleverages 说公司降低杠杆程度。偿还债务、增加权益资本等都可能改变相关比例，所以不能把它固定理解成“只能卖掉资产还钱”。它描述财务结构的调整。','deleverage the balance sheet；attempt to deleverage。','repay debt 是偿还某项债务；deleverage 强调整体杠杆下降，两者相关但不完全相同。',('The company used part of the proceeds to deleverage.','公司用部分所得资金来降低杠杆。'),('The report explains how several firms tried to deleverage after the downturn.','报告解释了几家公司在经济下行后如何尝试降低杠杆。'),sources=['https://www.imf.org/external/pubs/ft/fandd/2012/06/claessens.htm','https://en.wiktionary.org/wiki/deleverage']),
E('deleveraging','英 /diːˈliːvərɪdʒɪŋ/；美 /diːˈlevərɪdʒɪŋ/','去杠杆的过程；正在降低杠杆','把“逐渐降低债务相对负担”这段过程单独拿出来说。','deleverage 去词尾 e + -ing；可作动名词，也可构成进行时。',LE+[['英语 leverage → deleverage','形成财务杠杆 → 降低杠杆'],['英语 deleveraging','降低杠杆这一过程']],'corporate deleveraging 是企业部门减少杠杆的过程；a period of deleveraging 说一段财务调整时期。它不等于某家公司已经破产，也不必意味着所有债务一次归零。','a deleveraging process；household deleveraging；gradual deleveraging。','deleveraging 看的是变化过程；low leverage 描述某一时点杠杆较低的状态。',('Deleveraging remained a major theme in the annual report.','去杠杆仍是年度报告中的重要主题。'),('The study compared household deleveraging across several periods.','这项研究比较了几个时期家庭部门的去杠杆情况。'),sources=['https://www.imf.org/external/pubs/ft/fandd/2012/06/claessens.htm']),
E('levy','/ˈlevi/','征收〔税费〕；征集；征税额','把分散在各处的钱或人征集起来，凑成一笔款或一支队伍。','经盎格鲁法语 leve、古法语 levée“筹集、征收”，来自 lever“抬起、筹集”。',LY,'levy a tax 是征税；a levy on imports 是针对进口货物的一项征费。旧时 levy troops 是征集部队。这个词的核心是征集、征收，并非钱已经花到了哪里。','levy a tax on；impose a levy；a levy on something。','tax 可泛指税；levy 可作动词“征收”，也可作名词指某项征收。常见现代义不必与征兵捆在一起。',('The council decided to levy a small charge on parking.','委员会决定对停车征收一笔小额费用。'),('The proposal includes a levy on certain imports.','提案包含对某些进口货物征费的安排。'),sources=['https://www.etymonline.com/word/levy']),
E('leviable','/ˈleviəbəl/','可征收的；可被征取的〔正式〕','税款可以依法征收，或某些财物属于可征取的范围。','levy 的 y 变 i + -able。',A(LY,'英语 leviable','可以征收的；可被征取的'),'a tax leviable under a rule 是按该规则可以征收的税；leviable goods 是可被征取的财物。它通常出现在正式法规或税务文本里，学习时先抓住“可以 levy”即可。','tax leviable on；leviable under；leviable goods。','leviable 说具备可征收性；levied 表示已经被征收。二者有“可不可以”与“做没做”的区别。',('The document lists the taxes leviable under the scheme.','文件列出了该方案下可征收的税款。'),('The old manual distinguishes leviable goods from exempt property.','那本旧手册区分了可征取财物与豁免财产。'),sources=['https://www.collinsdictionary.com/dictionary/english/leviable']),
E('levee','堤岸义 /ˈlevi/；接见义亦见 /ˈleveɪ/','防洪堤、堤岸；正式接见〔历史用法〕','堤岸是沿水边抬高的土墙；宫廷接见义则来自君主起床时的接见。','两条法语借入路线：levée“抬高的东西”指堤；lever“起身”指晨间接见。它们最终都接 levare。',L+[['拉丁 levare → 法语 lever／levée','抬起、起身 → 抬高之物'],['一条支线：法语 levée → 英语 levee','抬高的岸堤'],['另一条支线：法语 lever → 英语 levee','起床时的接见 → 正式接见']],'沿河建的 levee 用来约束洪水，也有自然形成的河岸堆积。历史文字里的 a royal levee 则是正式接见，不能翻成“皇家防洪堤”；后来接见也不限定早晨或起床时举行。','a river levee；build a levee；a royal levee。','dam 通常横跨河道拦水；levee 通常沿河岸等地挡住外溢的水。levee 与 levy 同源却不是同一个现代词。',('Workers reinforced the levee before the rainy season.','工人在雨季前加固了防洪堤。'),('The diary describes a formal levee at the royal palace.','日记描述了王宫里的一次正式接见。'),sources=['https://www.etymonline.com/word/levee']),
]
